using BarisCemant.Verimor.Sms;
using System;
using System.Threading.Tasks;

namespace Examples.Operations.Sms
{
    public static class SendLegacyExample
    {
        public static async Task RunAsync()
        {
            var client = new SmsClient(new SmsClientOptions
            {
                Username = Environment.GetEnvironmentVariable("VERIMOR_SMS_USERNAME") ?? string.Empty,
                Password = Environment.GetEnvironmentVariable("VERIMOR_SMS_PASSWORD") ?? string.Empty,
                DefaultSender = Environment.GetEnvironmentVariable("VERIMOR_SMS_SENDER") ?? "VERIMOR",
                BaseUri = new Uri(Environment.GetEnvironmentVariable("VERIMOR_BASE_URL") ?? "https://sms.verimor.com.tr"),
            });
            var result = await client.Campaigns.SendLegacyAsync(
                dest: "905001112233",
                msg: "Merhaba"
            );
            Console.WriteLine(result);
        }
    }
}
